public class Solution {
    // CONTRACT: swap rows a and b of grid, in place.
    // Precondition: 0 <= a, b < grid.length.
    public static void swapRows(int[][] grid, int a, int b) {
        for (int c = 0; c < grid[0].length; c++) {
            grid[a][c] = grid[b][c];
        }
    }
}

